    static int[][][][] memo;
    static String numStr;

    public static int compute(int idx, int pCount, int nCount, int carryVal) {
        int trueCarry = carryVal - 50;
        if (idx == 17) {
            if (pCount + nCount + trueCarry == 0) {
                return 0;
            } else {
                return INF;
            }
        }
